{
  "assessment": "Egypt's economy shows steady, modest growth at 2.4% with easing inflation down to 25.7%, though structural pressures remain high. The public mood is calm, and domestic support across key sectors is strong, allowing the government to maintain its stable posture. Regionally, we face opportunities for strategic influence in North Africa and East Africa through positive diplomatic overtures from Libya, Sudan, and Somalia. We should reciprocate these overtures to secure our western and southern strategic depths while monitoring regional security closely. We will maintain monetary tightening to address high inflation and keep our spending balanced.",
  "directives": [
    {
      "type": "monetary_policy",
      "target": null,
      "amount": 0.5,
      "sub": "",
      "order": "Raise policy rate by 0.5 percentage points to continue cooling inflation."
    },
    {
      "type": "aid_give",
      "target": "SDN",
      "amount": 50,
      "sub": "",
      "order": "Provide 50 million USD in aid and intelligence support to Sudan to counter the RSF threat."
    }
  ],
  "cables": [
    {
      "to": "LBY",
      "private": true,
      "text": "Egypt welcomes your openness to constructive dialogue. We seek a stable, unified Libya free from foreign interference and are ready to discuss confidence-building measures."
    },
    {
      "to": "SDN",
      "private": true,
      "text": "We acknowledge your message and are prepared to enhance military and intelligence coordination to secure our shared stability against common threats."
    },
    {
      "to": "SOM",
      "private": true,
      "text": "Egypt values its historic ties with Somalia and agrees to deepen strategic and military cooperation to combat al-Shabaab and ensure regional security."
    }
  ],
  "public_statement": "Egypt remains committed to regional stability, economic reform, and the security of its borders. We are actively engaging with our African and Arab partners to foster peace, counter terrorism, and promote shared prosperity.",
  "standing_orders": [
    {
      "when": "inflation_above:20",
      "do": {
        "type": "monetary_policy",
        "target": null,
        "amount": 0.25,
        "sub": "",
        "order": "Adjust monetary policy to counter high inflation."
      }
    }
  ],
  "detailed_report": "military"
}
